fn parse_time_filter(s: &str) -> Option<(char, i64)> {
    let s = s.trim();
    if s.is_empty() { return None; }
    let mut chars = s.chars();
    let first = chars.next()?;
    let (sign, num_str) = if first == '+' || first == '-' {
        (first, chars.collect::<String>())
    } else {
        ('=', s.to_string())
    };
    if let Ok(days) = num_str.parse::<i64>() {
        Some((sign, days))
    } else {
        None
    }
}

fn check_time_filter(meta: &fs::Metadata, filter: &Option<(char, i64)>, which: &str) -> bool {
    if filter.is_none() {
        return true;
    }
    let (sign, days) = filter.as_ref().unwrap();
    let file_time = match which {
        "m" => meta.modified().ok(),
        "a" => meta.accessed().ok(),
        "c" => {
            // Use ctime from metadata
            // On unix, ctime is metadata change time
            let ctime = meta.ctime();
            // Convert to SystemTime? Approximate: use current time - ctime? Actually need to compare days.
            // We'll use system time from UNIX_EPOCH + ctime? Simpler: use metadata's ctime as seconds since epoch
            // We'll compute file age based on ctime
            // For simplicity, use modified as fallback if ctime not easy
            // Let's compute using ctime
            let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs() as i64;
            let age_secs = now - ctime;
            let age_days = age_secs / (24*3600);
            // Now apply filter logic similar to find -mtime
            // +n => age > n, -n => age < n, n => age == n
            // Actually dust description: +/-n matches files modified more/less than n days ago , and n matches files modified exactly n days ago, days are rounded down.That is +n => (−∞, curr−(n+1)), n => [curr−(n+1), curr−n), and -n => (curr−n, +∞)
            // So we need to compute file's mtime age in days rounded down, then compare.
            // For ctime filter, we already have age_days
            let days = *days;
            let result = match sign {
                '+' => age_days > days,
                '-' => age_days < *days,
                '=' => age_days == days,
                _ => true,
            };
            return result;
        }
        _ => None,
    };
    if which == "c" {
        // already handled
        return true;
    }
    if let Some(ft) = file_time {
        let now = SystemTime::now();
        let age = now.duration_since(ft).unwrap_or(std::time::Duration::from_secs(0));
        let age_days = age.as_secs() / (24*3600);
        let age_days = age_days as i64;
        let days = *days;
        match sign {
            '+' => age_days > days,
            '-' => age_days < days,
            '=' => age_days == days,
            _ => true,
        }
    } else {
        // If can't get time, include?
        true
    }
}

fn parse_min_size(s: &str) -> Option<u64> {
    // Support formats like "10M", "10K", "10", "1b" etc.
    let s = s.trim();
    if s.is_empty() { return None; }
    // Find where digits end and unit begins
    let mut num_str = String::new();
    let mut unit_str = String::new();
    let mut dot_seen = false;
    for c in s.chars() {
        if c.is_ascii_digit() || (c=='.' && !dot_seen) {
            if !unit_str.is_empty() { return None; }
            if c=='.' { dot_seen=true; }
            num_str.push(c);
        } else {
            unit_str.push(c);
        }
    }
    if num_str.is_empty() { return None; }
    let num: f64 = num_str.parse().ok()?;
    let unit = unit_str.to_lowercase();
    let mult: f64 = match unit.as_str() {
        "" | "b" => 1.0,
        "k" | "kb" | "kib" => 1024.0,
        "m" | "mb" | "mib" => 1024.0*1024.0,
        "g" | "gb" | "gib" => 1024.0*1024.0*1024.0,
        "t" | "tb" | "tib" => 1024.0*1024.0*1024.0*1024.0,
        "ki" => 1024.0,
        "mi" => 1024.0*1024.0,
        "gi" => 1024.0*1024.0*1024.0,
        "ti" => 1024.0*1024.0*1024.0*1024.0,
        _ => 1.0,
    };
    Some((num * mult) as u64)
}

