            }
        };
        for line in content.lines() {
            let line = line.trim();
            if line.is_empty() { continue; }
            match Regex::new(line) {
                Ok(r) => invert_regexes.push(r),
                Err(_) => {
                    // If not valid regex, treat as literal? But spec says regex matching that listed in this file.
                    // We'll try literal as regex escaped?
