        // However for non-tty, maybe default is something else. We'll use 30.
        30
    };

    // Parse output format
    let output_format = config.output_format.unwrap_or(OutputFormat::Default);

    // Determine filetime
    let filetime_type = if let Some(ref s) = config.filetime {
        match s.as_str() {
            "a" => Some(FileTime::Accessed),
            "c" => Some(FileTime::Changed),
            "m" => Some(FileTime::Modified),
            _ => None,
        }
    } else { None };

    // Collect input paths
    let mut input_paths: Vec<PathBuf> = Vec::new();

    if let Some(ref f) = files0_from_cli {
        let paths = if f == "-" {
            // read from stdin nul separated
            let mut buf = Vec::new();
            use std::io::Read;
            std::io::stdin().read_to_end(&mut buf).unwrap();
            buf.split(|b| *b==0).filter(|s| !s.is_empty()).map(|s| PathBuf::from(String::from_utf8_lossy(s).to_string())).collect::<Vec<_>>()
        } else {
            let content = fs::read(f).unwrap_or_default();
            content.split(|b| *b==0).filter(|s| !s.is_empty()).map(|s| PathBuf::from(String::from_utf8_lossy(s).to_string())).collect::<Vec<_>>()
