            let content = fs::read_to_string(f).unwrap_or_default();
            content.lines().map(|l| PathBuf::from(l.to_string())).collect::<Vec<_>>()
        };
        input_paths.extend(lines);
    }

    if !paths_cli.is_empty() {
        for p in paths_cli {
            input_paths.push(PathBuf::from(p));
        }
    } else if input_paths.is_empty() {
        input_paths.push(PathBuf::from("."));
    }

    // Validate output format for filetime interaction? filetime overrides size display with time string.

    // Walk filesystem to build tree
    // For file_types mode, we need to aggregate by extension, not build normal tree.

    if config.file_types {
        // File types mode: aggregate by extension
        let mut ext_map: HashMap<String, u64> = HashMap::new();
        let mut ext_count: HashMap<String, u64> = HashMap::new();
        let mut total_size: u64 = 0;
        let mut total_count: u64 = 0;

        let ignore_dirs_set: HashSet<String> = config.ignore_directory.iter().cloned().collect();
        let collapse_set: HashSet<String> = config.collapse.iter().cloned().collect();

        for input_path in &input_paths {
            // Walk recursively
            let mut stack = vec![input_path.clone()];
            let mut visited: HashSet<(u64,u64)> = HashSet::new(); // device,inode to avoid loops
            while let Some(path) = stack.pop() {
                let meta = if config.dereference_links {
                    fs::metadata(&path)
                } else {
                    fs::symlink_metadata(&path)
                };
                let meta = match meta {
                    Ok(m) => m,
                    Err(e) => {
                        if config.print_errors {
                            eprintln!("{}", path.display());
                        }
                        continue;
                    }
                };

                // Check hidden
                if config.ignore_hidden {
                    if let Some(name) = path.file_name().and_then(|n| n.to_str()) {
                        if name.starts_with('.') {
                            continue;
                        }
                    }
                }

                // Check ignore directory by name
                if let Some(name) = path.file_name().and_then(|n| n.to_str()) {
                    if ignore_dirs_set.contains(name) {
                        continue;
                    }
                }

                // Check filter/invert
                let path_str = path.to_string_lossy();
                if let Some(ref re) = filter_regex {
                    if !re.is_match(&path_str) {
                        // If it's a dir, we still need to walk inside? Filter only includes matching filepaths, so dir with no matching file should be excluded?
                        // For filetype mode, we only care about files that match filter.
                        // If dir doesn't match, we still walk inside to find matching files.
                        // So if path is dir and doesn't match, we still walk.
                        if !meta.is_dir() {
                            continue;
                        }
                    }
                }
                let mut excluded = false;
                for re in &invert_regexes {
                    if re.is_match(&path_str) {
                        excluded = true;
                        break;
                    }
                }
                if excluded {
                    continue;
                }

                // Check mtime/atime/ctime
                if !check_time_filter(&meta, &mtime_filter, "m") { continue; }
                if !check_time_filter(&meta, &atime_filter, "a") { 
                    // For atime, we need to check atime filter
                    // Our check_time_filter for atime uses accessed()
                    // Already handled for "a"
                    // Actually we called for "m" only, need separate
                    // We'll handle with same function but passing correct which
                    // For now, if atime filter present, check
                }
                // For simplicity, check all three separately
                if let Some(ref filt) = mtime_filter {
                    let ft = meta.modified().ok();
                    if let Some(ft) = ft {
                        let now = SystemTime::now();
                        let age = now.duration_since(ft).unwrap_or(std::time::Duration::from_secs(0)).as_secs() / (24*3600);
                        let age = age as i64;
                        let (sign, days) = filt;
                        let ok = match sign {
                            '+' => age > *days,
                            '-' => age < *days,
                            '=' => age == *days,
                            _ => true,
                        };
                        if !ok { continue; }
                    }
                }
                if let Some(ref filt) = atime_filter {
                    let ft = meta.accessed().ok();
                    if let Some(ft) = ft {
                        let now = SystemTime::now();
                        let age = now.duration_since(ft).unwrap_or(std::time::Duration::from_secs(0)).as_secs() / (24*3600);
                        let age = age as i64;
                        let (sign, days) = filt;
                        let ok = match sign {
                            '+' => age > *days,
                            '-' => age < *days,
                            '=' => age == *days,
                            _ => true,
                        };
                        if !ok { continue; }
                    }
                }
                if let Some(ref filt) = ctime_filter {
                    let ctime = meta.ctime() as i64;
                    let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs() as i64;
                    let age = (now - ctime) / (24*3600);
