fn parse_time_filter(s: &str) -> Option<(char, i64)> {
    let s = s.trim();
    if s.is_empty() { return None; }
    let mut chars = s.chars();
    let first = chars.next()?;
    let (sign, num_str) = if first == '+' || first == '-' {
        (first, chars.collect::<String>())
    } else {
        ('=', s.to_string())
    };
    if let Ok(days) = num_str.parse::<i64>() {
        Some((sign, days))
    } else {
        None
    }
}

