fn parse_time_filter(s: &str) -> Option<(char, i64)> {
    let s = s.trim();
    if s.is_empty() { return None; }
    let mut chars = s.chars();
    let first = chars.next()?;
    let (sign, num_str) = if first == '+' || first == '-' {
        (first, chars.collect::<String>())
    } else {
        ('=', s.to_string())
    };
    if let Ok(days) = num_str.parse::<i64>() {
        Some((sign, days))
    } else {
        None
    }
}

fn parse_min_size(s: &str) -> Option<u64> {
    let s = s.trim();
    if s.is_empty() { return None; }
    // parse number and unit
    let mut num_str = String::new();
    let mut unit_str = String::new();
    let mut dot_seen = false;
    for c in s.chars() {
        if c.is_ascii_digit() || c == '.' {
            if c == '.' {
                if dot_seen { return None; }
                dot_seen = true;
            }
            if !unit_str.is_empty() { return None; }
            num_str.push(c);
        } else {
            unit_str.push(c);
        }
    }
    if num_str.is_empty() { return None; }
    let num: f64 = num_str.parse().ok()?;
    let unit = unit_str.trim().to_lowercase();
    // Interpret as in dust: k=1024, m=1024^2, etc, but also kb=1000?
    // For min-size, dust seems to support K, M, G, T with 1024 base? Let's assume 1024.
    // Also support B
    let mult: f64 = match unit.as_str() {
        "" | "b" => 1.0,
        "k" | "kb" | "kib" | "ki" | "kib" => 1024.0,
        "m" | "mb" | "mib" | "mi" => 1024.0*1024.0,
        "g" | "gb" | "gib" | "gi" => 1024.0*1024.0*1024.0,
        "t" | "tb" | "tib" | "ti" => 1024.0*1024.0*1024.0*1024.0,
        _ => {
            // Try first char
            if unit.starts_with('k') { 1024.0 }
            else if unit.starts_with('m') { 1024.0*1024.0 }
            else if unit.starts_with('g') { 1024.0*1024.0*1024.0 }
            else if unit.starts_with('t') { 1024.0*1024.0*1024.0*1024.0 }
            else { 1.0 }
        }
    };
    Some((num * mult) as u64)
}

fn format_size_human(size: u64, base: u64) -> String {
    if size < base {
        return format!("{}B", size);
    }
    let units = ["B","K","M","G","T","P","E"];
    let mut s = size as f64;
    let mut unit_idx = 0;
    while s >= base as f64 && unit_idx < units.len()-1 {
        s /= base as f64;
        unit_idx += 1;
    }
    if unit_idx==0 {
        format!("{}B", size)
    } else {
        if s < 10.0 {
            format!("{:.1}{}", s, units[unit_idx])
        } else {
            format!("{:.0}{}", s.floor(), units[unit_idx])
        }
    }
}

fn format_size_default(size: u64) -> String {
    format_size_human(size, 1024)
}
fn format_size_si(size: u64) -> String {
    format_size_human(size, 1000)
}
fn format_size_b(size: u64) -> String {
    format!("{}B", size)
}
fn format_size_k(size: u64, base: u64) -> String {
    let v = size / base;
    format!("{}K", v)
}
fn format_size_m(size: u64, base: u64) -> String {
    let v = size / (base*base);
    format!("{}M", v)
}
fn format_size_g(size: u64, base: u64) -> String {
    let v = size / (base*base*base);
    format!("{}G", v)
}
fn format_size_t(size: u64, base: u64) -> String {
    let v = size / (base*base*base*base);
    format!("{}T", v)
}

