fn format_size_k(size: u64, base: u64) -> String { format!("{}K", size/base) }
fn format_size_m(size: u64, base: u64) -> String { format!("{}M", size/(base*base)) }
fn format_size_g(size: u64, base: u64) -> String { format!("{}G", size/(base*base*base)) }
fn format_size_t(size: u64, base: u64) -> String { format!("{}T", size/(base*base*base*base)) }
