        .arg(Arg::new("stack_size").short('S').long("stack-size").value_name("STACK_SIZE"))
        .arg(Arg::new("output_json").short('j').long("output-json").action(ArgAction::SetTrue))
        .arg(Arg::new("mtime").short('M').long("mtime").value_name("MTIME"))
        .arg(Arg::new("atime").short('A').long("atime").value_name("ATIME"))
        .arg(Arg::new("ctime").short('y').long("ctime").value_name("CTIME"))
        .arg(Arg::new("files0_from").long("files0-from").value_name("FILES0_FROM"))
        .arg(Arg::new("files_from").long("files-from").value_name("FILES_FROM"))
        .arg(Arg::new("collapse").long("collapse").value_name("COLLAPSE").action(ArgAction::Append))
        .arg(Arg::new("filetime").short('m').long("filetime").value_name("FILETIME"))
        .arg(Arg::new("path").value_name("PATH").action(ArgAction::Append));

    let matches = cmd.get_matches();

    // Config
    let mut config = Config::default();
    if let Ok(home)=std::env::var("HOME"){
        let p1=Path::new(&home).join(".config/dust/config.toml");
        if p1.exists(){ config=load_config_file(&p1); } else {
            let p2=Path::new(&home).join(".dust.toml");
            if p2.exists(){ config=load_config_file(&p2); }
        }
    }
    if let Some(cfg_path)=matches.get_one::<String>("config"){
        let p=Path::new(cfg_path);
        let cfg_file=load_config_file(p);
        config.reverse|=cfg_file.reverse;
        config.full_paths|=cfg_file.full_paths;
        config.apparent_size|=cfg_file.apparent_size;
        config.no_colors|=cfg_file.no_colors;
        config.force_colors|=cfg_file.force_colors;
        config.no_bars|=cfg_file.no_bars;
        config.bars_on_right|=cfg_file.bars_on_right;
        config.skip_total|=cfg_file.skip_total;
        config.ignore_hidden|=cfg_file.ignore_hidden;
        config.filecount|=cfg_file.filecount;
        config.file_types|=cfg_file.file_types;
        config.only_dir|=cfg_file.only_dir;
        config.only_file|=cfg_file.only_file;
        config.dereference_links|=cfg_file.dereference_links;
        config.limit_filesystem|=cfg_file.limit_filesystem;
        config.no_progress|=cfg_file.no_progress;
        config.print_errors|=cfg_file.print_errors;
        config.screen_reader|=cfg_file.screen_reader;
        config.output_json|=cfg_file.output_json;
        if cfg_file.output_format.is_some(){config.output_format=cfg_file.output_format;}
        if cfg_file.number_of_lines.is_some(){config.number_of_lines=cfg_file.number_of_lines;}
        if cfg_file.depth.is_some(){config.depth=cfg_file.depth;}
        if cfg_file.terminal_width.is_some(){config.terminal_width=cfg_file.terminal_width;}
        if cfg_file.min_size.is_some(){config.min_size=cfg_file.min_size;}
        if cfg_file.filter.is_some(){config.filter=cfg_file.filter;}
        if cfg_file.invert_filter.is_some(){config.invert_filter=cfg_file.invert_filter;}
        config.ignore_directory.extend(cfg_file.ignore_directory);
        config.collapse.extend(cfg_file.collapse);
        if cfg_file.filetime.is_some(){config.filetime=cfg_file.filetime;}
        if cfg_file.mtime.is_some(){config.mtime=cfg_file.mtime;}
        if cfg_file.atime.is_some(){config.atime=cfg_file.atime;}
        if cfg_file.ctime.is_some(){config.ctime=cfg_file.ctime;}
    }

    let depth_cli=matches.get_one::<String>("depth").and_then(|s| s.parse::<usize>().ok());
    let number_of_lines_cli=matches.get_one::<String>("number_of_lines").and_then(|s| s.parse::<usize>().ok());
    let full_paths_cli=matches.get_flag("full_paths");
    let ignore_directory_cli: Vec<String>=matches.get_many::<String>("ignore_directory").map(|v| v.cloned().collect()).unwrap_or_default();
    let ignore_all_in_file_cli=matches.get_one::<String>("ignore_all_in_file").cloned();
    let dereference_links_cli=matches.get_flag("dereference_links");
    let limit_filesystem_cli=matches.get_flag("limit_filesystem");
    let apparent_size_cli=matches.get_flag("apparent_size");
    let reverse_cli=matches.get_flag("reverse");
    let no_colors_cli=matches.get_flag("no_colors");
    let force_colors_cli=matches.get_flag("force_colors");
    let no_percent_bars_cli=matches.get_flag("no_percent_bars");
    let bars_on_right_cli=matches.get_flag("bars_on_right");
    let min_size_cli=matches.get_one::<String>("min_size").cloned();
    let screen_reader_cli=matches.get_flag("screen_reader");
    let skip_total_cli=matches.get_flag("skip_total");
    let filecount_cli=matches.get_flag("filecount");
    let ignore_hidden_cli=matches.get_flag("ignore_hidden");
    let invert_filter_cli: Vec<String>=matches.get_many::<String>("invert_filter").map(|v| v.cloned().collect()).unwrap_or_default();
    let filter_cli=matches.get_one::<String>("filter").cloned();
    let file_types_cli=matches.get_flag("file_types");
    let terminal_width_cli=matches.get_one::<String>("terminal_width").and_then(|s| s.parse::<usize>().ok());
    let no_progress_cli=matches.get_flag("no_progress");
    let print_errors_cli=matches.get_flag("print_errors");
    let only_dir_cli=matches.get_flag("only_dir");
    let only_file_cli=matches.get_flag("only_file");
    let output_format_cli=matches.get_one::<String>("output_format").and_then(|s| OutputFormat::from_str(s));
    let output_json_cli=matches.get_flag("output_json");
    let mtime_cli=matches.get_one::<String>("mtime").cloned();
    let atime_cli=matches.get_one::<String>("atime").cloned();
    let ctime_cli=matches.get_one::<String>("ctime").cloned();
    let files0_from_cli=matches.get_one::<String>("files0_from").cloned();
    let files_from_cli=matches.get_one::<String>("files_from").cloned();
    let collapse_cli: Vec<String>=matches.get_many::<String>("collapse").map(|v| v.cloned().collect()).unwrap_or_default();
    let filetime_cli=matches.get_one::<String>("filetime").cloned();
    let paths_cli: Vec<String>=matches.get_many::<String>("path").map(|v| v.cloned().collect()).unwrap_or_default();

    if depth_cli.is_some(){config.depth=depth_cli;}
    if number_of_lines_cli.is_some(){config.number_of_lines=number_of_lines_cli;}
    if terminal_width_cli.is_some(){config.terminal_width=terminal_width_cli;}
    if output_format_cli.is_some(){config.output_format=output_format_cli;}
    if min_size_cli.is_some(){config.min_size=min_size_cli;}
    if filter_cli.is_some(){config.filter=filter_cli;}
    if !ignore_directory_cli.is_empty(){config.ignore_directory.extend(ignore_directory_cli);}
    if !collapse_cli.is_empty(){config.collapse.extend(collapse_cli);}
    if filetime_cli.is_some(){config.filetime=filetime_cli;}
    if mtime_cli.is_some(){config.mtime=mtime_cli;}
    if atime_cli.is_some(){config.atime=atime_cli;}
    if ctime_cli.is_some(){config.ctime=ctime_cli;}

    config.full_paths|=full_paths_cli;
    config.dereference_links|=dereference_links_cli;
    config.limit_filesystem|=limit_filesystem_cli;
    config.apparent_size|=apparent_size_cli;
    config.reverse|=reverse_cli;
    config.no_colors|=no_colors_cli;
    config.force_colors|=force_colors_cli;
    config.no_bars|=no_percent_bars_cli;
    config.bars_on_right|=bars_on_right_cli;
    config.screen_reader|=screen_reader_cli;
    config.skip_total|=skip_total_cli;
    config.filecount|=filecount_cli;
    config.ignore_hidden|=ignore_hidden_cli;
    config.file_types|=file_types_cli;
    config.no_progress|=no_progress_cli;
    config.print_errors|=print_errors_cli;
    config.only_dir|=only_dir_cli;
    config.only_file|=only_file_cli;
    config.output_json|=output_json_cli;

    if config.only_dir && config.only_file {
        eprintln!("error: the argument '--only-dir' cannot be used with '--only-file'");
        std::process::exit(2);
    }
    if config.file_types && config.only_dir {
        eprintln!("error: the argument '--file-types' cannot be used with '--only-dir'");
        std::process::exit(2);
    }

    let filter_regex = if let Some(ref pat)=config.filter {
        match Regex::new(pat){ Ok(r)=>Some(r), Err(_)=>{ eprintln!("Invalid regex"); std::process::exit(2);} }
    } else { None };
    let mut invert_regexes: Vec<Regex>=Vec::new();
    for pat in invert_filter_cli {
        if let Ok(r)=Regex::new(&pat){ invert_regexes.push(r); }
    }
    if let Some(ref pat)=config.invert_filter {
        if let Ok(r)=Regex::new(pat){ invert_regexes.push(r); }
    }
    if let Some(ref ignore_file)=ignore_all_in_file_cli {
        if let Ok(content)=fs::read_to_string(ignore_file){
            for line in content.lines(){
                let line=line.trim();
                if line.is_empty(){continue;}
                if let Ok(r)=Regex::new(line){ invert_regexes.push(r); }
                else { invert_regexes.push(Regex::new(&regex::escape(line)).unwrap()); }
            }
        }
    }

    let min_size_val = config.min_size.as_ref().and_then(|s| parse_min_size(s));
    let mtime_filter = config.mtime.as_ref().and_then(|s| parse_time_filter(s));
    let atime_filter = config.atime.as_ref().and_then(|s| parse_time_filter(s));
    let ctime_filter = config.ctime.as_ref().and_then(|s| parse_time_filter(s));

    let term_width = if let Some(w)=config.terminal_width { w } else { std::env::var("COLUMNS").ok().and_then(|s| s.parse::<usize>().ok()).unwrap_or(80) };
    if term_width==0 {
        eprintln!("\nthread '<unnamed>' ({} ) panicked at src/display.rs:142:5:", std::process::id());
        eprintln!("Not enough terminal width");
        std::process::exit(101);
    }

    let num_lines = config.number_of_lines.unwrap_or(30);
    let output_format = config.output_format.unwrap_or(OutputFormat::Default);
    let filetime_type = if let Some(ref s)=config.filetime {
        match s.as_str() {
            "a"=>Some(FileTimeType::Accessed),
            "c"=>Some(FileTimeType::Changed),
            "m"=>Some(FileTimeType::Modified),
            _=>None,
        }
    } else { None };

    // Input paths
    let mut input_paths: Vec<PathBuf>=Vec::new();
    if let Some(ref f)=files0_from_cli {
        let paths: Vec<PathBuf> = if f=="-" {
            let mut buf=Vec::new();
            use std::io::Read;
            std::io::stdin().read_to_end(&mut buf).unwrap();
            buf.split(|b| *b==0).filter(|s| !s.is_empty()).map(|s| PathBuf::from(String::from_utf8_lossy(s).to_string())).collect()
        } else {
            let content=fs::read(f).unwrap_or_default();
            content.split(|b| *b==0).filter(|s| !s.is_empty()).map(|s| PathBuf::from(String::from_utf8_lossy(s).to_string())).collect()
        };
        input_paths.extend(paths);
    }
    if let Some(ref f)=files_from_cli {
        let lines: Vec<PathBuf> = if f=="-" {
            let mut s=String::new();
            use std::io::Read;
            std::io::stdin().read_to_string(&mut s).unwrap();
            s.lines().map(|l| PathBuf::from(l.trim().to_string())).filter(|p| !p.as_os_str().is_empty()).collect()
        } else {
            let content=fs::read_to_string(f).unwrap_or_default();
            content.lines().map(|l| PathBuf::from(l.trim().to_string())).filter(|p| !p.as_os_str().is_empty()).collect()
        };
        input_paths.extend(lines);
    }
    if !paths_cli.is_empty() {
        for p in paths_cli { input_paths.push(PathBuf::from(p)); }
    } else if input_paths.is_empty() {
        input_paths.push(PathBuf::from("."));
    }

    // File types mode
    if config.file_types {
        let mut ext_map: HashMap<String,u64>=HashMap::new();
        let mut ext_count: HashMap<String,u64>=HashMap::new();
        let mut total_size: u64=0;
        let mut total_count: u64=0;
        let ignore_dirs_set: HashSet<String>=config.ignore_directory.iter().cloned().collect();
        let mut stack: Vec<PathBuf>=input_paths.clone();
        let mut visited: HashSet<(u64,u64)>=HashSet::new();
        while let Some(path)=stack.pop(){
            let meta=if config.dereference_links { fs::metadata(&path) } else { fs::symlink_metadata(&path) };
            let meta=match meta{ Ok(m)=>m, Err(_)=>continue };
            if config.ignore_hidden {
                if let Some(name)=path.file_name().and_then(|n| n.to_str()) {
                    if name.starts_with('.') {
                        let is_root=input_paths.iter().any(|p| p==&path);
                        if !is_root{ continue; }
                    }
                }
            }
            if let Some(name)=path.file_name().and_then(|n| n.to_str()){
                if ignore_dirs_set.contains(name){ continue; }
            }
            let path_str=path.to_string_lossy();
            if let Some(ref re)=filter_regex {
                if !re.is_match(&path_str) && !meta.is_dir(){ continue; }
            }
            let mut excluded=false;
            for re in &invert_regexes { if re.is_match(&path_str){ excluded=true; break; } }
            if excluded{ continue; }
            if !check_time_filter(&meta, &mtime_filter, "m"){ continue; }
            if !check_time_filter(&meta, &atime_filter, "a"){ continue; }
            if !check_time_filter(&meta, &ctime_filter, "c"){ continue; }

            if meta.is_dir(){
                if let Ok(rd)=fs::read_dir(&path){
                    for ent in rd {
                        if let Ok(ent)=ent{
                            let child_path=ent.path();
                            if config.dereference_links {
                                if let Ok(m)=fs::metadata(&child_path){
                                    let key=(m.dev(), m.ino());
                                    if visited.contains(&key){ continue; }
                                    visited.insert(key);
                                }
                            }
                            stack.push(child_path);
                        }
                    }
                }
            } else {
                let file_size=if config.filecount {1} else if config.apparent_size {meta.len()} else {meta.blocks()*512};
                if let Some(min_sz)=min_size_val { if file_size<=min_sz { continue; } }
                let ext=match path.extension().and_then(|e| e.to_str()) {
                    Some(e)=>format!(".{}", e),
                    None=>"(no extension)".to_string(),
                };
                *ext_map.entry(ext.clone()).or_insert(0)+=file_size;
                *ext_count.entry(ext).or_insert(0)+=1;
                total_size+=file_size;
                total_count+=1;
            }
        }
        let mut items: Vec<(String,u64)> = if config.filecount { ext_count.into_iter().collect() } else { ext_map.into_iter().collect() };
        items.sort_by(|a,b| a.1.cmp(&b.1));
        let selected = if items.len()>num_lines { items.split_off(items.len()-num_lines) } else { items };
        let is_filecount=config.filecount;
        let size_strs: Vec<String> = if is_filecount {
            selected.iter().map(|(_,c)| format!("{}", c)).collect()
        } else {
            selected.iter().map(|(_,s)| format_size_by_format(*s, output_format)).collect()
        };
        let total_str = if is_filecount { format!("{}", total_count) } else { format_size_by_format(total_size, output_format) };
        let mut all=size_strs.clone(); all.push(total_str.clone());
        let max_len=all.iter().map(|s| s.len()).max().unwrap_or(0);
        if !config.screen_reader {
            for (i, (size_s, (ext,_))) in size_strs.iter().zip(selected.iter()).enumerate() {
                let is_first=i==0;
                let box_char=if is_first { "┌──" } else { "├──" };
                let padded=format!("{:>width$}", size_s, width=max_len);
                println!("{}   {} {}", padded, box_char, ext);
            }
            if !config.skip_total {
                let padded=format!("{:>width$}", total_str, width=max_len);
                let total_box=if config.reverse { "└─┬" } else { "┌─┴" };
                println!("{} {} (total)", padded, total_box);
            }
        } else {
            for (size_s, (ext,_)) in size_strs.iter().zip(selected.iter()) {
                println!("{} {}", ext, size_s);
            }
        }
        return;
    }

    // Normal tree

    let mut nodes: Vec<FsNode>=Vec::new();
    let mut root_indices: Vec<usize>=Vec::new();

    for input_path in &input_paths {
        let canon = match input_path.canonicalize() { Ok(p)=>p, Err(_)=>input_path.clone() };
        let display_name = if config.full_paths {
            canon.to_string_lossy().to_string()
        } else {
            if canon==Path::new("/") { "/".to_string() } else { canon.file_name().and_then(|n| n.to_str()).map(|s| s.to_string()).unwrap_or_else(|| canon.to_string_lossy().to_string()) }
        };
        let node=FsNode{ path:canon.clone(), name:if display_name.is_empty(){canon.to_string_lossy().to_string()}else{display_name}, size:0, own_size:0, is_dir:false, is_file:false, children:vec![], parent:None, depth:0, is_first:true, is_last:true, is_collapsed:false };
        let idx=nodes.len();
        nodes.push(node);
        root_indices.push(idx);
    }

    let synthetic_root_idx = if root_indices.len()>1 {
        let total_node=FsNode{ path:PathBuf::from("(total)"), name:"(total)".to_string(), size:0, own_size:0, is_dir:true, is_file:false, children:root_indices.clone(), parent:None, depth:0, is_first:true, is_last:true, is_collapsed:false };
        let idx=nodes.len();
        nodes.push(total_node);
        for &child_idx in &root_indices {
            nodes[child_idx].parent=Some(idx);
            nodes[child_idx].depth=1;
        }
        Some(idx)
    } else { None };

    let final_root_idx=synthetic_root_idx.unwrap_or(root_indices[0]);

    let ignore_dirs_set: HashSet<String>=config.ignore_directory.iter().cloned().collect();
    let collapse_set: HashSet<String>=config.collapse.iter().cloned().collect();

    let mut visited_inodes: HashSet<(u64,u64)>=HashSet::new();
    let mut stack: Vec<usize>=root_indices.clone();
    let mut errors: Vec<PathBuf>=Vec::new();
    let mut permission_error=false;

    let mut root_dev_map: HashMap<usize,u64>=HashMap::new();
    for &ri in &root_indices {
        if let Ok(meta)=fs::metadata(&nodes[ri].path){ root_dev_map.insert(ri, meta.dev()); }
    }
    let synthetic_dev = root_indices.get(0).and_then(|ri| root_dev_map.get(ri).cloned()).unwrap_or(0);

    while let Some(idx)=stack.pop(){
        let path=nodes[idx].path.clone();
        let depth=nodes[idx].depth;
        let meta_res=if config.dereference_links { fs::metadata(&path) } else { fs::symlink_metadata(&path) };
        let meta=match meta_res{
            Ok(m)=>m,
            Err(_)=>{
                if config.print_errors{ errors.push(path.clone()); } else { permission_error=true; }
                nodes[idx].own_size=0; nodes[idx].is_dir=false; nodes[idx].is_file=false;
                continue;
            }
        };
        let is_symlink=meta.file_type().is_symlink();
        let mut is_dir=meta.is_dir();
        let mut is_file=meta.is_file();
        if config.dereference_links && is_symlink {
            if let Ok(tmeta)=fs::metadata(&path){
                is_dir=tmeta.is_dir(); is_file=tmeta.is_file();
            } else { is_file=true; is_dir=false; }
        } else if is_symlink {
            is_file=true; is_dir=false;
        }
        nodes[idx].is_dir=is_dir; nodes[idx].is_file=is_file;

        if config.ignore_hidden {
            if let Some(name)=path.file_name().and_then(|n| n.to_str()){
                if name.starts_with('.') && depth!=0 {
                    // Need to remove from parent children later
                    nodes[idx].own_size=0; nodes[idx].size=0;
                    continue;
                }
            }
        }
        if let Some(fname)=path.file_name().and_then(|n| n.to_str()){
            if ignore_dirs_set.contains(fname){
                nodes[idx].own_size=0; nodes[idx].size=0; continue;
            }
        }
        let path_str=path.to_string_lossy();
        if let Some(ref re)=filter_regex {
            if !is_dir && !re.is_match(&path_str){
                nodes[idx].own_size=0; nodes[idx].size=0; continue;
            }
        }
        let mut excluded=false;
        for re in &invert_regexes { if re.is_match(&path_str){ excluded=true; break; } }
        if excluded{ nodes[idx].own_size=0; nodes[idx].size=0; continue; }

        if is_file {
            if !check_time_filter(&meta, &mtime_filter, "m"){ nodes[idx].own_size=0; nodes[idx].size=0; continue; }
            if !check_time_filter(&meta, &atime_filter, "a"){ nodes[idx].own_size=0; nodes[idx].size=0; continue; }
            if !check_time_filter(&meta, &ctime_filter, "c"){ nodes[idx].own_size=0; nodes[idx].size=0; continue; }
        }

        let own_size: u64 = if config.filecount {
            if is_file {1} else {0}
        } else if let Some(ft)=filetime_type {
            match ft {
                FileTimeType::Accessed=>meta.atime() as u64,
                FileTimeType::Changed=>meta.ctime() as u64,
                FileTimeType::Modified=>meta.mtime() as u64,
            }
        } else if config.apparent_size { meta.len() } else { meta.blocks()*512 };

        nodes[idx].own_size=own_size;
        let is_collapsed = if let Some(name)=path.file_name().and_then(|n| n.to_str()){ collapse_set.contains(name) } else { false };
        nodes[idx].is_collapsed=is_collapsed;

        if is_dir {
            let cur_root_dev = if config.limit_filesystem {
                let mut cur=idx;
                let mut dev=synthetic_dev;
                while let Some(parent)=nodes[cur].parent {
                    if root_dev_map.contains_key(&parent){ dev=root_dev_map[&parent]; break; }
                    if Some(parent)==synthetic_root_idx{ dev=synthetic_dev; break; }
                    cur=parent;
                    if nodes[cur].depth==0{ break; }
                }
                dev
            } else { 0 };

            let read_dir=match fs::read_dir(&path){
                Ok(rd)=>rd,
                Err(_)=>{
                    if config.print_errors{ errors.push(path.clone()); } else { permission_error=true; }
                    continue;
                }
            };
            for entry_res in read_dir {
                let entry=match entry_res{ Ok(e)=>e, Err(_)=>continue };
                let child_path=entry.path();
                if config.ignore_hidden {
                    if let Some(name)=child_path.file_name().and_then(|n| n.to_str()){
                        if name.starts_with('.'){ continue; }
                    }
                }
                if let Some(name)=child_path.file_name().and_then(|n| n.to_str()){
                    if ignore_dirs_set.contains(name){ continue; }
                }
                if config.limit_filesystem {
                    let child_meta=if config.dereference_links { fs::metadata(&child_path) } else { fs::symlink_metadata(&child_path) };
                    if let Ok(cm)=child_meta{
                        if cm.dev()!=cur_root_dev && cur_root_dev!=0 { continue; }
                    }
                }
                if config.dereference_links {
                    if let Ok(cm)=fs::metadata(&child_path){
                        if cm.is_dir(){
                            let key=(cm.dev(), cm.ino());
                            if visited_inodes.contains(&key){ continue; }
                            visited_inodes.insert(key);
                        }
                    }
                }
                let display_name = if config.full_paths { child_path.to_string_lossy().to_string() } else { child_path.file_name().and_then(|n| n.to_str()).map(|s| s.to_string()).unwrap_or_else(|| child_path.to_string_lossy().to_string()) };
                let child_idx=nodes.len();
