            // total line width currently without bar: size (max_len) + 3 spaces + indent.len() + box_str.len() (3) +1 + name.len()
            // For simplicity, use byte len for name (not display width, but approximate)
            let cur_len = max_size_len + 3 + indent.len() + 3 + 1 + name.len();
            let mut bar_width = if term_width > cur_len + 10 {
                term_width - cur_len - 10 // reserve for " │ 100%" maybe 10 chars
            } else { 0 };
            // But dust's bar width seems to be maybe 50? Let's attempt to compute more accurately from observed.
            // In earlier -w 80 example, with size 4.0K, indent, box, name "secret", bar width maybe 10? Let's attempt to measure: line "4.0K     ┌── secret    │█████████                                         │  17%" - after name "secret", there are 4 spaces then "│", then bar "█████████" (9 filled) plus many spaces (empty), then " │  17%"
            // So bar width includes filled + empty.

            // For now, we will compute bar_width = term_width - cur_len - 8 (for " │ │ 100%")?
            // Let's approximate bar_width = term_width.saturating_sub(cur_len + 10);

            if bar_width>0 {
                let filled = ((percent as f64 / 100.0) * bar_width as f64).round() as usize;
                let empty = bar_width - filled;
                let bar = format!("{}{}", "█".repeat(filled), "░".repeat(empty));
                if config.bars_on_right {
                    // Bars on right: size, indent, box, name, bar, percent ?
                    // Earlier bars_on_right example: "4.0K       ┌── file.txt│ ... │  20%"
                    // So format: size, indent, box, name, "│", bar, " │", percent
                    println!("{}   {}{} {}│{}│ {:>3}%", padded_size, indent, box_str, colored_name, bar, percent);
                } else {
                    // Normal bars left? Actually example: size, box, name, "│", bar, "│", percent
                    // Wait earlier example with -w 80: "4.0K     ┌── secret    │█████████                                         │  17%"
                    // So after name, spaces, then "│", bar, "│", percent
                    // We have name, then bar.
                    println!("{}   {}{} {} │{}│ {:>3}%", padded_size, indent, box_str, colored_name, bar, percent);
                }
            } else {
                println!("{}   {}{} {}", padded_size, indent, box_str, colored_name);
            }
        }
    }

    // For permission error message if needed and no_progress false already printed?

    if permission_error && !config.no_progress && !config.print_errors {
        eprintln!("Did not have permissions for all directories (add --print-errors to see errors)");
    }
    if config.print_errors {
        if !errors.is_empty() {
            eprintln!("Did not have permissions for directories: {}", errors.iter().map(|p| p.display().to_string()).collect::<Vec<_>>().join(", "));
        }
        // Also print each error path?
        for e in errors {
            eprintln!("{}", e.display());
        }
    }
}
RS
