#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum OutputFormat { Default, Si, B, K, M, G, T, Kb, Mb, Gb, Tb, }
impl OutputFormat {
    fn from_str(s: &str) -> Option<Self> {
        match s.to_lowercase().as_str() {
            "si"=>Some(Self::Si),
            "b"=>Some(Self::B),
            "k"|"kib"|"ki"=>Some(Self::K),
