}
impl Default for Config {
    fn default()->Self{ Self{reverse:false,full_paths:false,apparent_size:false,no_colors:false,force_colors:false,no_bars:false,bars_on_right:false,skip_total:false,ignore_hidden:false,output_format:None,number_of_lines:None,depth:None,terminal_width:None,min_size:None,filecount:false,file_types:false,only_dir:false,only_file:false,dereference_links:false,limit_filesystem:false,no_progress:false,print_errors:false,screen_reader:false,output_json:false,filter:None,invert_filter:None,ignore_directory:vec![],collapse:vec![],filetime:None,mtime:None,atime:None,ctime:None} }
}
#[derive(Deserialize, Debug)]
struct TomlConfig {
    reverse: Option<bool>,
    #[serde(rename="display-full-paths")] display_full_paths: Option<bool>,
    #[serde(rename="display-apparent-size")] display_apparent_size: Option<bool>,
    #[serde(rename="no-colors")] no_colors: Option<bool>,
    #[serde(rename="force-colors")] force_colors: Option<bool>,
    #[serde(rename="no-bars")] no_bars: Option<bool>,
    #[serde(rename="no-percent-bars")] no_percent_bars: Option<bool>,
    #[serde(rename="bars-on-right")] bars_on_right: Option<bool>,
    #[serde(rename="skip-total")] skip_total: Option<bool>,
    #[serde(rename="ignore-hidden")] ignore_hidden: Option<bool>,
    #[serde(rename="output-format")] output_format: Option<String>,
    #[serde(rename="number-of-lines")] number_of_lines: Option<usize>,
    depth: Option<usize>,
    #[serde(rename="terminal-width")] terminal_width: Option<usize>,
    #[serde(rename="min-size")] min_size: Option<String>,
    filecount: Option<bool>,
    #[serde(rename="display-filecount")] display_filecount: Option<bool>,
    #[serde(rename="file-types")] file_types: Option<bool>,
    #[serde(rename="only-dir")] only_dir: Option<bool>,
    #[serde(rename="only-file")] only_file: Option<bool>,
    #[serde(rename="dereference-links")] dereference_links: Option<bool>,
    #[serde(rename="limit-filesystem")] limit_filesystem: Option<bool>,
    #[serde(rename="no-progress")] no_progress: Option<bool>,
    #[serde(rename="print-errors")] print_errors: Option<bool>,
    #[serde(rename="screen-reader")] screen_reader: Option<bool>,
    #[serde(rename="output-json")] output_json: Option<bool>,
    filter: Option<String>,
    #[serde(rename="invert-filter")] invert_filter: Option<String>,
    #[serde(rename="ignore-directory")] ignore_directory: Option<String>,
    collapse: Option<toml::Value>,
    filetime: Option<String>,
    mtime: Option<String>,
    atime: Option<String>,
    ctime: Option<String>,
}
fn load_config_file(path: &Path) -> Config {
    let mut cfg = Config::default();
    let content=match fs::read_to_string(path){Ok(c)=>c,Err(_)=>return cfg};
    if let Ok(toml_cfg)=toml::from_str::<TomlConfig>(&content){
        apply_toml_config(&mut cfg, toml_cfg);
        return cfg;
    }
    if let Ok(yaml_cfg)=serde_yaml::from_str::<TomlConfig>(&content){
        apply_toml_config(&mut cfg, yaml_cfg);
    }
    cfg
}
fn apply_toml_config(cfg: &mut Config, tc: TomlConfig){
    if let Some(v)=tc.reverse {cfg.reverse=v;}
    if let Some(v)=tc.display_full_paths {cfg.full_paths=v;}
    if let Some(v)=tc.display_apparent_size {cfg.apparent_size=v;}
    if let Some(v)=tc.no_colors {cfg.no_colors=v;}
    if let Some(v)=tc.force_colors {cfg.force_colors=v;}
    if let Some(v)=tc.no_bars {cfg.no_bars=v;}
    if let Some(v)=tc.no_percent_bars {cfg.no_bars=v;}
    if let Some(v)=tc.bars_on_right {cfg.bars_on_right=v;}
    if let Some(v)=tc.skip_total {cfg.skip_total=v;}
    if let Some(v)=tc.ignore_hidden {cfg.ignore_hidden=v;}
    if let Some(v)=tc.output_format {if let Some(f)=OutputFormat::from_str(&v){cfg.output_format=Some(f);}}
    if let Some(v)=tc.number_of_lines {cfg.number_of_lines=Some(v);}
    if let Some(v)=tc.depth {cfg.depth=Some(v);}
    if let Some(v)=tc.terminal_width {cfg.terminal_width=Some(v);}
    if let Some(v)=tc.min_size {cfg.min_size=Some(v);}
    if let Some(v)=tc.filecount {cfg.filecount=v;}
    if let Some(v)=tc.display_filecount {cfg.filecount=v;}
    if let Some(v)=tc.file_types {cfg.file_types=v;}
    if let Some(v)=tc.only_dir {cfg.only_dir=v;}
    if let Some(v)=tc.only_file {cfg.only_file=v;}
    if let Some(v)=tc.dereference_links {cfg.dereference_links=v;}
    if let Some(v)=tc.limit_filesystem {cfg.limit_filesystem=v;}
    if let Some(v)=tc.no_progress {cfg.no_progress=v;}
    if let Some(v)=tc.print_errors {cfg.print_errors=v;}
    if let Some(v)=tc.screen_reader {cfg.screen_reader=v;}
    if let Some(v)=tc.output_json {cfg.output_json=v;}
    if let Some(v)=tc.filter {cfg.filter=Some(v);}
    if let Some(v)=tc.invert_filter {cfg.invert_filter=Some(v);}
    if let Some(v)=tc.ignore_directory {cfg.ignore_directory.push(v);}
    if let Some(v)=tc.collapse {
        match v {
            toml::Value::String(s)=>cfg.collapse.push(s),
            toml::Value::Array(arr)=>{ for it in arr { if let toml::Value::String(s)=it { cfg.collapse.push(s); } } },
            _=>{}
        }
    }
    if let Some(v)=tc.filetime {cfg.filetime=Some(v);}
    if let Some(v)=tc.mtime {cfg.mtime=Some(v);}
    if let Some(v)=tc.atime {cfg.atime=Some(v);}
    if let Some(v)=tc.ctime {cfg.ctime=Some(v);}
}
fn parse_time_filter(s: &str)->Option<(char,i64)>{
    let s=s.trim(); if s.is_empty(){return None;}
    let mut chars=s.chars(); let first=chars.next()?;
    let (sign,num_str)=if first=='+'||first=='-' {(first, chars.collect::<String>())} else {('=', s.to_string())};
    if let Ok(days)=num_str.parse::<i64>(){Some((sign,days))} else {None}
}
fn parse_min_size(s: &str)->Option<u64>{
    let s=s.trim(); if s.is_empty(){return None;}
    let mut num_str=String::new(); let mut unit_str=String::new();
    for c in s.chars(){
        if c.is_ascii_digit() || c=='.' {
            if !unit_str.is_empty(){return None;}
            num_str.push(c);
        } else { unit_str.push(c); }
    }
    if num_str.is_empty(){return None;}
    let num: f64=num_str.parse().ok()?;
    let unit=unit_str.trim().to_lowercase();
    let mult: f64=match unit.as_str(){
        ""|"b"=>1.0,
        "k"|"kb"|"kib"|"ki"=>1024.0,
        "m"|"mb"|"mib"|"mi"=>1024.0*1024.0,
        "g"|"gb"|"gib"|"gi"=>1024.0*1024.0*1024.0,
        "t"|"tb"|"tib"|"ti"=>1024.0*1024.0*1024.0*1024.0,
        _=>{ if unit.starts_with('k'){1024.0} else if unit.starts_with('m'){1024.0*1024.0} else if unit.starts_with('g'){1024.0*1024.0*1024.0} else if unit.starts_with('t'){1024.0*1024.0*1024.0*1024.0} else {1.0} }
    };
    Some((num*mult) as u64)
}
fn format_size_human(size: u64, base: u64)->String{
    if size < base { return format!("{}B", size); }
    let units=["B","K","M","G","T","P","E"];
    let mut s=size as f64; let mut idx=0;
    while s>=base as f64 && idx < units.len()-1 { s/=base as f64; idx+=1; }
    if idx==0 { format!("{}B", size) }
    else if s<10.0 { format!("{:.1}{}", s, units[idx]) }
    else { format!("{:.0}{}", s.floor(), units[idx]) }
}
fn format_size_default(size: u64)->String{ format_size_human(size,1024) }
fn format_size_si(size: u64)->String{ format_size_human(size,1000) }
fn format_size_b(size: u64)->String{ format!("{}B", size) }
fn format_size_k(size: u64, base: u64)->String{ format!("{}K", size/base) }
fn format_size_m(size: u64, base: u64)->String{ format!("{}M", size/(base*base)) }
fn format_size_g(size: u64, base: u64)->String{ format!("{}G", size/(base*base*base)) }
fn format_size_t(size: u64, base: u64)->String{ format!("{}T", size/(base*base*base*base)) }
fn check_time_filter(meta: &fs::Metadata, filter: &Option<(char,i64)>, kind: &str)->bool{
    if filter.is_none(){return true;}
    let (sign, days)=filter.as_ref().unwrap();
    match kind {
        "c"=>{
            let ctime=meta.ctime() as i64;
            let now=SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs() as i64;
            let age=(now-ctime)/(24*3600);
            match sign {'+'=>age>*days,'-'=>age<*days,'='=>age==*days,_=>true}
        },
        "m"=>{
            if let Ok(ft)=meta.modified(){
                let now=SystemTime::now();
                let age=now.duration_since(ft).unwrap_or(std::time::Duration::from_secs(0)).as_secs() as i64 / (24*3600);
                match sign {'+'=>age>*days,'-'=>age<*days,'='=>age==*days,_=>true}
            } else { true }
        },
        "a"=>{
            if let Ok(ft)=meta.accessed(){
                let now=SystemTime::now();
                let age=now.duration_since(ft).unwrap_or(std::time::Duration::from_secs(0)).as_secs() as i64 / (24*3600);
                match sign {'+'=>age>*days,'-'=>age<*days,'='=>age==*days,_=>true}
            } else { true }
        },
        _=>true,
    }
}
fn format_size_by_format(size: u64, fmt: OutputFormat)->String{
    match fmt {
        OutputFormat::Default=>format_size_default(size),
        OutputFormat::Si=>format_size_si(size),
        OutputFormat::B=>format_size_b(size),
        OutputFormat::K=>format_size_k(size,1024),
        OutputFormat::M=>format_size_m(size,1024),
        OutputFormat::G=>format_size_g(size,1024),
        OutputFormat::T=>format_size_t(size,1024),
        OutputFormat::Kb=>format_size_k(size,1000),
        OutputFormat::Mb=>format_size_m(size,1000),
        OutputFormat::Gb=>format_size_g(size,1000),
        OutputFormat::Tb=>format_size_t(size,1000),
    }
}
#[derive(Debug, Clone)]
struct FsNode {
    path: PathBuf,
    name: String,
    size: u64,
    own_size: u64,
    is_dir: bool,
    is_file: bool,
    children: Vec<usize>,
    parent: Option<usize>,
    depth: usize,
    is_first: bool,
    is_last: bool,
    is_collapsed: bool,
}
#[derive(serde::Serialize)]
struct JsonNode {
    size: String,
    name: String,
    children: Vec<JsonNode>,
}

fn main(){
    let mut cmd = Command::new("dust")
        .version("1.2.3")
        .about("Like du but more intuitive")
        .arg(Arg::new("depth").short('d').long("depth").value_name("DEPTH"))
        .arg(Arg::new("threads").short('T').long("threads").value_name("THREADS"))
