        .arg(Arg::new("ignore_directory").short('X').long("ignore-directory").value_name("PATH").action(ArgAction::Append))
        .arg(Arg::new("ignore_all_in_file").short('I').long("ignore-all-in-file").value_name("FILE"))
        .arg(Arg::new("dereference_links").short('L').long("dereference-links").action(ArgAction::SetTrue))
