        .arg(Arg::new("no_percent_bars").short('b').long("no-percent-bars").action(ArgAction::SetTrue))
        .arg(Arg::new("bars_on_right").short('B').long("bars-on-right").action(ArgAction::SetTrue))
        .arg(Arg::new("min_size").short('z').long("min-size").value_name("MIN_SIZE"))
