fn load_config_file(path: &Path) -> Config {
    let mut cfg = Config::default();
    let content=match fs::read_to_string(path){Ok(c)=>c,Err(_)=>return cfg};
    if let Ok(toml_cfg)=toml::from_str::<TomlConfig>(&content){
        apply_toml_config(&mut cfg, toml_cfg);
        return cfg;
    }
    if let Ok(yaml_cfg)=serde_yaml::from_str::<TomlConfig>(&content){
        apply_toml_config(&mut cfg, yaml_cfg);
    }
    cfg
}
fn apply_toml_config(cfg: &mut Config, tc: TomlConfig){
