    if let Some(v)=tc.output_format {if let Some(f)=OutputFormat::from_str(&v){cfg.output_format=Some(f);}}
    if let Some(v)=tc.number_of_lines {cfg.number_of_lines=Some(v);}
    if let Some(v)=tc.depth {cfg.depth=Some(v);}
    if let Some(v)=tc.terminal_width {cfg.terminal_width=Some(v);}
