    if let Some(v)=tc.file_types {cfg.file_types=v;}
    if let Some(v)=tc.only_dir {cfg.only_dir=v;}
    if let Some(v)=tc.only_file {cfg.only_file=v;}
    if let Some(v)=tc.dereference_links {cfg.dereference_links=v;}
    if let Some(v)=tc.limit_filesystem {cfg.limit_filesystem=v;}
