    if let Some(v)=tc.screen_reader {cfg.screen_reader=v;}
    if let Some(v)=tc.output_json {cfg.output_json=v;}
    if let Some(v)=tc.filter {cfg.filter=Some(v);}
    if let Some(v)=tc.invert_filter {cfg.invert_filter=Some(v);}
    if let Some(v)=tc.ignore_directory {cfg.ignore_directory.push(v);}
    if let Some(v)=tc.collapse {
        match v {
            toml::Value::String(s)=>cfg.collapse.push(s),
            toml::Value::Array(arr)=>{ for it in arr { if let toml::Value::String(s)=it { cfg.collapse.push(s); } } },
