        }
    }
    if let Some(v)=tc.filetime {cfg.filetime=Some(v);}
    if let Some(v)=tc.mtime {cfg.mtime=Some(v);}
    if let Some(v)=tc.atime {cfg.atime=Some(v);}
    if let Some(v)=tc.ctime {cfg.ctime=Some(v);}
}
fn parse_time_filter(s: &str)->Option<(char,i64)>{
    let s=s.trim(); if s.is_empty(){return None;}
    let mut chars=s.chars(); let first=chars.next()?;
    let (sign,num_str)=if first=='+'||first=='-' {(first, chars.collect::<String>())} else {('=', s.to_string())};
    if let Ok(days)=num_str.parse::<i64>(){Some((sign,days))} else {None}
}
fn parse_min_size(s: &str)->Option<u64>{
    let s=s.trim(); if s.is_empty(){return None;}
    let mut num_str=String::new(); let mut unit_str=String::new();
    for c in s.chars(){
        if c.is_ascii_digit() || c=='.' {
            if !unit_str.is_empty(){return None;}
            num_str.push(c);
        } else { unit_str.push(c); }
    }
    if num_str.is_empty(){return None;}
    let num: f64=num_str.parse().ok()?;
    let unit=unit_str.trim().to_lowercase();
    let mult: f64=match unit.as_str(){
        ""|"b"=>1.0,
        "k"|"kb"|"kib"|"ki"=>1024.0,
        "m"|"mb"|"mib"|"mi"=>1024.0*1024.0,
        "g"|"gb"|"gib"|"gi"=>1024.0*1024.0*1024.0,
        "t"|"tb"|"tib"|"ti"=>1024.0*1024.0*1024.0*1024.0,
        _=>{ if unit.starts_with('k'){1024.0} else if unit.starts_with('m'){1024.0*1024.0} else if unit.starts_with('g'){1024.0*1024.0*1024.0} else if unit.starts_with('t'){1024.0*1024.0*1024.0*1024.0} else {1.0} }
    };
    Some((num*mult) as u64)
}
fn format_size_human(size: u64, base: u64)->String{
    if size < base { return format!("{}B", size); }
    let units=["B","K","M","G","T","P","E"];
    let mut s=size as f64; let mut idx=0;
    while s>=base as f64 && idx < units.len()-1 { s/=base as f64; idx+=1; }
    if idx==0 { format!("{}B", size) }
    else if s<10.0 { format!("{:.1}{}", s, units[idx]) }
    else { format!("{:.0}{}", s.floor(), units[idx]) }
}
fn format_size_default(size: u64)->String{ format_size_human(size,1024) }
fn format_size_si(size: u64)->String{ format_size_human(size,1000) }
fn format_size_b(size: u64)->String{ format!("{}B", size) }
fn format_size_k(size: u64, base: u64)->String{ format!("{}K", size/base) }
fn format_size_m(size: u64, base: u64)->String{ format!("{}M", size/(base*base)) }
fn format_size_g(size: u64, base: u64)->String{ format!("{}G", size/(base*base*base)) }
fn format_size_t(size: u64, base: u64)->String{ format!("{}T", size/(base*base*base*base)) }
fn check_time_filter(meta: &fs::Metadata, filter: &Option<(char,i64)>, kind: &str)->bool{
    if filter.is_none(){return true;}
    let (sign, days)=filter.as_ref().unwrap();
    match kind {
        "c"=>{
            let ctime=meta.ctime() as i64;
            let now=SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs() as i64;
            let age=(now-ctime)/(24*3600);
            match sign {'+'=>age>*days,'-'=>age<*days,'='=>age==*days,_=>true}
        },
        "m"=>{
            if let Ok(ft)=meta.modified(){
                let now=SystemTime::now();
                let age=now.duration_since(ft).unwrap_or(std::time::Duration::from_secs(0)).as_secs() as i64 / (24*3600);
                match sign {'+'=>age>*days,'-'=>age<*days,'='=>age==*days,_=>true}
            } else { true }
        },
        "a"=>{
            if let Ok(ft)=meta.accessed(){
                let now=SystemTime::now();
                let age=now.duration_since(ft).unwrap_or(std::time::Duration::from_secs(0)).as_secs() as i64 / (24*3600);
                match sign {'+'=>age>*days,'-'=>age<*days,'='=>age==*days,_=>true}
            } else { true }
        },
        _=>true,
    }
}
fn format_size_by_format(size: u64, fmt: OutputFormat)->String{
    match fmt {
        OutputFormat::Default=>format_size_default(size),
        OutputFormat::Si=>format_size_si(size),
        OutputFormat::B=>format_size_b(size),
        OutputFormat::K=>format_size_k(size,1024),
        OutputFormat::M=>format_size_m(size,1024),
        OutputFormat::G=>format_size_g(size,1024),
        OutputFormat::T=>format_size_t(size,1024),
        OutputFormat::Kb=>format_size_k(size,1000),
        OutputFormat::Mb=>format_size_m(size,1000),
        OutputFormat::Gb=>format_size_g(size,1000),
        OutputFormat::Tb=>format_size_t(size,1000),
    }
}
